/**
 * Unit tests for CategoryPlot.getRangeAxisIndex.
 */
public class CategoryPlot_getRangeAxisIndex_TriageGen0Test {

    private CategoryPlot categoryPlot;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
    }

    /**
     * Tests the case where the axis is found directly within the CategoryPlot's range axes.
     * Covers the branch where result >= 0.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInCurrentPlot() {
        ValueAxis axis = mock(ValueAxis.class);
        categoryPlot.setRangeAxis(axis);
        // Index should be 0
        int result = categoryPlot.getRangeAxisIndex(axis);
        assertEquals(0, result);
    }

    /**
     * Tests the case where the axis is NOT in the current plot, but the parent is a CategoryPlot.
     * It should delegate to the parent's getRangeAxisIndex.
     * Covers the branch where result < 0 and parent instanceof CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrent_FoundInParentCategoryPlot() {
        // Create a parent CategoryPlot
        CategoryPlot parentPlot = mock(CategoryPlot.class);
        ValueAxis axis = mock(ValueAxis.class);

        // Mock the hierarchy: categoryPlot is a child of parentPlot
        // Note: In JFreeChart, Plot.setParent is usually used. 
        // Since we cannot easily set parent via public API in all versions without a Chart, 
        // we simulate the logic using a spy or mock if possible, but here we rely on the implementation 
        // that getParent() is called. 
        // For the sake of this test, we assume we can manipulate the parent via reflection or 
        // that the test environment allows mocking the getParent() call.

        CategoryPlot spyPlot = org.mockito.Mockito.spy(categoryPlot);
        when(spyPlot.getParent()).thenReturn(parentPlot);
        when(parentPlot.getRangeAxisIndex(axis)).thenReturn(2);

        int result = spyPlot.getRangeAxisIndex(axis);
        assertEquals(2, result);
    }

    /**
     * Tests the case where the axis is NOT in the current plot, and the parent is NOT a CategoryPlot.
     * Covers the branch where result < 0 and parent is NOT an instance of CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrent_ParentIsNotCategoryPlot() {
        // Create a parent that is a different type of Plot (e.g., XYPlot)
        Plot nonCategoryParent = mock(Plot.class);
        ValueAxis axis = mock(ValueAxis.class);

        CategoryPlot spyPlot = org.mockito.Mockito.spy(categoryPlot);
        when(spyPlot.getParent()).thenReturn(nonCategoryParent);

        int result = spyPlot.getRangeAxisIndex(axis);
        // Should return -1 because it's not in current and parent is not CategoryPlot
        assertEquals(-1, result);
    }

    /**
     * Tests the case where the axis is NOT in the current plot and there is no parent.
     * Covers the branch where result < 0 and getParent() returns null.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInCurrent_NoParent() {
        ValueAxis axis = mock(ValueAxis.class);

        CategoryPlot spyPlot = org.mockito.Mockito.spy(categoryPlot);
        when(spyPlot.getParent()).thenReturn(null);

        int result = spyPlot.getRangeAxisIndex(axis);
        assertEquals(-1, result);
    }
}
